//
// Pack integrity — the embedded snapshot must match its own manifest.
//
// The manifest (generated by the spec's showcase-projector) carries a
// sha256_16 over the LEAN text of every workflow. Re-hashing the
// embedded bytes here means a tampered, truncated or drifted vendored
// pack fails `cargo test` — the binary can never silently ship a pack
// that disagrees with the spec version it claims.

use sha2::{Digest, Sha256};

fn sha256_16(text: &str) -> String {
    // the manifest hashes lean + trailing newline (python lean() keeps it)
    let mut h = Sha256::new();
    h.update(text.as_bytes());
    h.update(b"\n");
    let digest = h.finalize();
    digest.iter().take(8).map(|b| format!("{b:02x}")).collect()
}

/// Parse `file:` / `sha256_16:` pairs out of the manifest.
fn manifest_entries() -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut current: Option<String> = None;
    for line in nika_pack::manifest().lines() {
        let line = line.trim();
        if let Some(f) = line.strip_prefix("- file: ") {
            current = Some(f.trim().to_owned());
        } else if let Some(h) = line.strip_prefix("sha256_16: ")
            && let Some(f) = current.take()
        {
            out.push((f, h.trim().to_owned()));
        }
    }
    out
}

#[test]
fn version_is_nonempty_and_matches_manifest() {
    let v = nika_pack::pack_version();
    assert!(!v.is_empty());
    let line = format!("pack_version: {v}");
    assert!(
        nika_pack::manifest().contains(&line),
        "manifest pack_version must equal the embedded VERSION ({v})"
    );
}

#[test]
fn every_manifest_entry_resolves_and_hashes_clean() {
    let entries = manifest_entries();
    assert!(
        entries.len() >= 27,
        "expected the full pack · got {}",
        entries.len()
    );
    for (file, expected) in entries {
        let slug = file
            .strip_prefix("examples/")
            .map(|s| s.to_owned())
            .or_else(|| {
                file.strip_prefix("templates/")
                    .map(|s| format!("templates::{s}"))
            });
        let text = match slug {
            Some(s) if s.starts_with("templates::") => {
                nika_pack::template(s.trim_start_matches("templates::"))
            }
            Some(s) => nika_pack::example(&s),
            None => None,
        };
        let text = text.unwrap_or_else(|| panic!("manifest entry {file} not embedded"));
        let lean = nika_pack::lean(text);
        assert_eq!(
            sha256_16(lean),
            expected,
            "embedded {file} drifted from its manifest hash"
        );
    }
}

#[test]
fn surface_counts_hold() {
    assert_eq!(nika_pack::template_names().len(), 6);
    assert!(nika_pack::example_slugs().len() >= 27);
    assert!(nika_pack::doc_paths().len() >= 12, "spec + stdlib pages");
    assert!(nika_pack::schema_json().contains("\"$schema\""));
    assert!(nika_pack::canon().contains("schema_version:"));
    assert!(!nika_pack::quickstart().is_empty());
}

#[test]
fn lean_strips_the_banner_and_nothing_else() {
    let text = "# SPDX\n# banner\nnika: v1\nworkflow: x\n";
    assert_eq!(nika_pack::lean(text), "nika: v1\nworkflow: x");
    // no banner → identity
    assert_eq!(nika_pack::lean("nika: v1\n"), "nika: v1");
}
